window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b8cc5c2834dd3832"]={"versions": [{"id": "FIG-b8cc5c2834dd3832", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt der AUTOSAR Adaptive Platform / <em>TPS Manifest Specification</em>).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation des Metamodells zur typisierten Anbindung von DoIP-spezifischen Steuerungs- und Signalisierungsfunktionen zwischen der AUTOSAR Adaptive Plattform (insbesondere dem Diagnostic Management / DoIP-Daemon) und Applikationen bzw. Basissoftware-Diensten. Es implementiert <code>RS_MANI_00061</code> (<em>Support the modeling of Diagnostic Port Interfaces</em>) und standardisiert portschnittstellenseitig die Interaktion für hardwarenahe und protokollspezifische DoIP-Funktionen (ISO 13400).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Basisklassen & Metamodell-Eigenschaften</p>\n<ul class=\"fig-list\">\n<li><strong><code>PortInterface</code>:</strong></li>\n<li>Abstrakte Wurzel für alle Port-Schnittstellen in AUTOSAR.</li>\n<li>Typisiert als <code>ARElement</code> (erstklassiges, im ARXML-Paketbaum eigenständig referenzierbares Modellierungselement).</li>\n<li>Stereotypen/Attribute: <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code> (kann als Blueprint-Schablone definiert und abgeleitet werden), <code>«AtpType»</code> (fungiert als Schnittstellentyp für PortPrototypes).</li>\n<li><strong><code>DiagnosticPortInterface</code>:</strong></li>\n<li>Spezialisierung von <code>PortInterface</code>.</li>\n<li>Dient als generische Basisklasse für sämtliche diagnostikspezifischen Port-Schnittstellen (Diagnostic Management) im Adaptive Service- bzw. Komponentenmodell.</li>\n</ul>\n<p class=\"fig-p\">#### DoIP-spezifische Spezialisierungen (<code>DiagnosticPortInterface</code>)</p>\n<p class=\"fig-p\">Alle Subklassen erben transitiv die <code>PortInterface</code>-Eigenschaften und spezialisieren die Semantik für DoIP-Ereignisse und -Zustände:</p>\n<ol class=\"fig-list\">\n<li><strong><code>DiagnosticDoIPGroupIdentificationInterface</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Schnittstelle zur dynamischen Ermittlung oder Konfiguration der DoIP-Entity-/Gruppen-Identifikation (<em>Entity Group Identification</em> gemäß ISO 13400-2).</li>\n<li>Erlaubt dem DoIP-Stack, Gruppenidentifikationsdaten für Routing- und Adressierungszwecke abzufragen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>DiagnosticDoIPTriggerVehicleAnnouncementInterface</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Triggerschnittstelle zur Initiierung von DoIP-<em>Vehicle Announcement Messages</em> (VAM).</li>\n<li>Ermöglicht externen oder internen Funktionen (z. B. Network Management, State Management), ein erneutes Versenden der Fahrzeugidentifikationsnachricht via UDP-Broadcast/Multicast anzustoßen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>DiagnosticDoIPActivationLineInterface</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signalisiert den logischen Zustand der hardwareseitigen DoIP-Aktivierungslinie (<em>DoIP Activation Line</em> gemäß ISO 13400-2, Pin- oder Wake-Up-basiert).</li>\n<li>Steuert das Aktivieren/Deaktivieren der DoIP-Kommunikation und der TCP/UDP-Server-Sockets im Stack.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>DiagnosticDoIPPowerModeInterface</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Rückmeldeschnittstelle für den aktuellen Energiemodus (<em>Power Mode</em>) des Steuergeräts/Fahrzeugs.</li>\n<li>Liefert den Zustand an den DoIP-Daemon zur Beantwortung von <em>Diagnostic Power Mode Information Requests</em> des externen DoIP-Testers.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell-Diagramm handelt, sind Laufzeitflüsse nicht direkt abgebildet. Das abgeleitete Zusammenspiel im System gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\">\n<li><strong>Aktivierung & Sockets (Activation Line):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein I/O-Treiber oder Hardware-Monitor detektiert Pegelwechsel an der physischen DoIP-Aktivierungsleitung.</li>\n<li>Benachrichtigung des Diagnostic Managers über einen Port mit <code>DiagnosticDoIPActivationLineInterface</code>.</li>\n<li>Der DoIP-Stack aktiviert seine IP-Sockets und startet die DoIP-Initialisierung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Vehicle Announcement:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Verbindungsaufbau (Link-Up/DHCP) oder getriggert via <code>DiagnosticDoIPTriggerVehicleAnnouncementInterface</code> sendet der DoIP-Stack bis zu 3x die Vehicle Announcement Message (VAM) an den Multicast-/Broadcast-Port 13400.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Statusabfragen (Power Mode & Group ID):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Geht ein DoIP-Request (z. B. <em>Power Mode Information Request</em>) vom Tester ein, ruft der Stack synchron/asynchron über das <code>DiagnosticDoIPPowerModeInterface</code> den Zustand beim Platform State Management ab und formuliert die DoIP-Response.</li>\n<li>Bei Gruppenzuordnung greift der Stack über das <code>DiagnosticDoIPGroupIdentificationInterface</code> auf hinterlegte Routing-Parameter zu.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Modellierung (ARXML):</strong></li>\n<li>Ports an <code>AdaptiveApplication</code>s oder Plattform-Daemons müssen explizit mit einer dieser Schnittstellen typisiert werden (<code>provided</code> oder <code>required PortPrototype</code>).</li>\n<li>Ein Service Instance Manifest mappt diese Port-Interfaces auf ara::com-Services oder plattforminterne direkte IPC-Bindings des Diagnostic Managers (DM).</li>\n<li><strong>API- & C++-Stack-Vertrag (<code>ara::diag</code>):</strong></li>\n<li>Implementierende Komponenten stellen Callback-Klassen bzw. Observer bereit, die den Schnittstellenfunktionalitäten entsprechen (z. B. Abfrage-Methoden für Power Mode oder Events für Statusänderungen der Activation Line).</li>\n<li>Fehlende oder inkorrekte Port-Definitionen im Execution Manifest verhindern das standardkonforme Starten des DoIP-Daemons bzw. führen zur Verweigerung von ISO 13400-Konformitätstests.</li>\n<li><strong>Systemintegration:</strong></li>\n<li>Entwickler von State Management und I/O-Basissoftware müssen zwingend das <code>DiagnosticDoIPActivationLineInterface</code> bedienen, um DoIP normgerecht (Batterieschutz bei ausgeschalteter Zündung) freizugeben oder schlafen zu legen.</li>\n</ul>"}, {"id": "FIG-35b7b7ef71de12fe", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt der AUTOSAR Adaptive Platform / <em>TPS Manifest Specification</em>).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation des Metamodells zur typisierten Anbindung von DoIP-spezifischen Steuerungs- und Signalisierungsfunktionen zwischen der AUTOSAR Adaptive Plattform (insbesondere dem Diagnostic Management / DoIP-Daemon) und Applikationen bzw. Basissoftware-Diensten. Es implementiert <code>RS_MANI_00061</code> (<em>Support the modeling of Diagnostic Port Interfaces</em>) und standardisiert portschnittstellenseitig die Interaktion für hardwarenahe und protokollspezifische DoIP-Funktionen (ISO 13400).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Basisklassen & Metamodell-Eigenschaften</p>\n<ul class=\"fig-list\">\n<li><strong><code>PortInterface</code>:</strong></li>\n<li>Abstrakte Wurzel für alle Port-Schnittstellen in AUTOSAR.</li>\n<li>Typisiert als <code>ARElement</code> (erstklassiges, im ARXML-Paketbaum eigenständig referenzierbares Modellierungselement).</li>\n<li>Stereotypen/Attribute: <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code> (kann als Blueprint-Schablone definiert und abgeleitet werden), <code>«AtpType»</code> (fungiert als Schnittstellentyp für PortPrototypes).</li>\n<li><strong><code>DiagnosticPortInterface</code>:</strong></li>\n<li>Spezialisierung von <code>PortInterface</code>.</li>\n<li>Dient als generische Basisklasse für sämtliche diagnostikspezifischen Port-Schnittstellen (Diagnostic Management) im Adaptive Service- bzw. Komponentenmodell.</li>\n</ul>\n<p class=\"fig-p\">#### DoIP-spezifische Spezialisierungen (<code>DiagnosticPortInterface</code>)</p>\n<p class=\"fig-p\">Alle Subklassen erben transitiv die <code>PortInterface</code>-Eigenschaften und spezialisieren die Semantik für DoIP-Ereignisse und -Zustände:</p>\n<ol class=\"fig-list\">\n<li><strong><code>DiagnosticDoIPGroupIdentificationInterface</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Schnittstelle zur dynamischen Ermittlung oder Konfiguration der DoIP-Entity-/Gruppen-Identifikation (<em>Entity Group Identification</em> gemäß ISO 13400-2).</li>\n<li>Erlaubt dem DoIP-Stack, Gruppenidentifikationsdaten für Routing- und Adressierungszwecke abzufragen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>DiagnosticDoIPTriggerVehicleAnnouncementInterface</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Triggerschnittstelle zur Initiierung von DoIP-<em>Vehicle Announcement Messages</em> (VAM).</li>\n<li>Ermöglicht externen oder internen Funktionen (z. B. Network Management, State Management), ein erneutes Versenden der Fahrzeugidentifikationsnachricht via UDP-Broadcast/Multicast anzustoßen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>DiagnosticDoIPActivationLineInterface</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signalisiert den logischen Zustand der hardwareseitigen DoIP-Aktivierungslinie (<em>DoIP Activation Line</em> gemäß ISO 13400-2, Pin- oder Wake-Up-basiert).</li>\n<li>Steuert das Aktivieren/Deaktivieren der DoIP-Kommunikation und der TCP/UDP-Server-Sockets im Stack.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>DiagnosticDoIPPowerModeInterface</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Rückmeldeschnittstelle für den aktuellen Energiemodus (<em>Power Mode</em>) des Steuergeräts/Fahrzeugs.</li>\n<li>Liefert den Zustand an den DoIP-Daemon zur Beantwortung von <em>Diagnostic Power Mode Information Requests</em> des externen DoIP-Testers.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell-Diagramm handelt, sind Laufzeitflüsse nicht direkt abgebildet. Das abgeleitete Zusammenspiel im System gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\">\n<li><strong>Aktivierung & Sockets (Activation Line):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein I/O-Treiber oder Hardware-Monitor detektiert Pegelwechsel an der physischen DoIP-Aktivierungsleitung.</li>\n<li>Benachrichtigung des Diagnostic Managers über einen Port mit <code>DiagnosticDoIPActivationLineInterface</code>.</li>\n<li>Der DoIP-Stack aktiviert seine IP-Sockets und startet die DoIP-Initialisierung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Vehicle Announcement:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Verbindungsaufbau (Link-Up/DHCP) oder getriggert via <code>DiagnosticDoIPTriggerVehicleAnnouncementInterface</code> sendet der DoIP-Stack bis zu 3x die Vehicle Announcement Message (VAM) an den Multicast-/Broadcast-Port 13400.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Statusabfragen (Power Mode & Group ID):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Geht ein DoIP-Request (z. B. <em>Power Mode Information Request</em>) vom Tester ein, ruft der Stack synchron/asynchron über das <code>DiagnosticDoIPPowerModeInterface</code> den Zustand beim Platform State Management ab und formuliert die DoIP-Response.</li>\n<li>Bei Gruppenzuordnung greift der Stack über das <code>DiagnosticDoIPGroupIdentificationInterface</code> auf hinterlegte Routing-Parameter zu.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Modellierung (ARXML):</strong></li>\n<li>Ports an <code>AdaptiveApplication</code>s oder Plattform-Daemons müssen explizit mit einer dieser Schnittstellen typisiert werden (<code>provided</code> oder <code>required PortPrototype</code>).</li>\n<li>Ein Service Instance Manifest mappt diese Port-Interfaces auf ara::com-Services oder plattforminterne direkte IPC-Bindings des Diagnostic Managers (DM).</li>\n<li><strong>API- & C++-Stack-Vertrag (<code>ara::diag</code>):</strong></li>\n<li>Implementierende Komponenten stellen Callback-Klassen bzw. Observer bereit, die den Schnittstellenfunktionalitäten entsprechen (z. B. Abfrage-Methoden für Power Mode oder Events für Statusänderungen der Activation Line).</li>\n<li>Fehlende oder inkorrekte Port-Definitionen im Execution Manifest verhindern das standardkonforme Starten des DoIP-Daemons bzw. führen zur Verweigerung von ISO 13400-Konformitätstests.</li>\n<li><strong>Systemintegration:</strong></li>\n<li>Entwickler von State Management und I/O-Basissoftware müssen zwingend das <code>DiagnosticDoIPActivationLineInterface</code> bedienen, um DoIP normgerecht (Batterieschutz bei ausgeschalteter Zündung) freizugeben oder schlafen zu legen.</li>\n</ul>"}, {"id": "FIG-230ed2690c04d519", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt der AUTOSAR Adaptive Platform / <em>TPS Manifest Specification</em>).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation des Metamodells zur typisierten Anbindung von DoIP-spezifischen Steuerungs- und Signalisierungsfunktionen zwischen der AUTOSAR Adaptive Plattform (insbesondere dem Diagnostic Management / DoIP-Daemon) und Applikationen bzw. Basissoftware-Diensten. Es implementiert <code>RS_MANI_00061</code> (<em>Support the modeling of Diagnostic Port Interfaces</em>) und standardisiert portschnittstellenseitig die Interaktion für hardwarenahe und protokollspezifische DoIP-Funktionen (ISO 13400).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Basisklassen & Metamodell-Eigenschaften</p>\n<ul class=\"fig-list\">\n<li><strong><code>PortInterface</code>:</strong></li>\n<li>Abstrakte Basisklasse aller Port-Schnittstellen im AUTOSAR-Metamodell.</li>\n<li>Im Diagramm als übergeordnete Basisklasse im Header von <code>DiagnosticPortInterface</code> referenziert (anstatt als eigenständiges Klassenelement dargestellt).</li>\n<li><strong><code>DiagnosticPortInterface</code>:</strong></li>\n<li>Abstrakte Spezialisierung von <code>PortInterface</code> (kursiv dargestellt).</li>\n<li>Dient als generische Basisklasse für sämtliche diagnostikspezifischen Port-Schnittstellen (Diagnostic Management) im AUTOSAR Adaptive Platform Modell.</li>\n</ul>\n<p class=\"fig-p\">#### DoIP-spezifische Spezialisierungen (<code>DiagnosticPortInterface</code>)</p>\n<p class=\"fig-p\">Alle Subklassen erben transitiv die <code>PortInterface</code>-Eigenschaften und spezialisieren die Semantik für DoIP-Ereignisse und -Zustände gemäß ISO 13400:</p>\n<ol class=\"fig-list\">\n<li><strong><code>DiagnosticDoIPGroupIdentificationInterface</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Schnittstelle zur dynamischen Ermittlung oder Konfiguration der DoIP-Entity-/Gruppen-Identifikation (<em>Entity Group Identification</em> gemäß ISO 13400-2).</li>\n<li>Erlaubt dem DoIP-Stack, Gruppenidentifikationsdaten für Routing- und Adressierungszwecke abzufragen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>DiagnosticDoIPTriggerVehicleAnnouncementInterface</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Triggerschnittstelle zur Initiierung von DoIP-<em>Vehicle Announcement Messages</em> (VAM).</li>\n<li>Ermöglicht externen oder internen Funktionen (z. B. Network Management, State Management), ein erneutes Versenden der Fahrzeugidentifikationsnachricht via UDP-Broadcast/Multicast anzustoßen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>DiagnosticDoIPActivationLineInterface</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signalisiert den logischen Zustand der hardwareseitigen DoIP-Aktivierungslinie (<em>DoIP Activation Line</em> gemäß ISO 13400-2).</li>\n<li>Steuert das Aktivieren/Deaktivieren der DoIP-Kommunikation und der TCP/UDP-Server-Sockets im Stack.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>DiagnosticDoIPPowerModeInterface</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Rückmeldeschnittstelle für den aktuellen Energiemodus (<em>Power Mode</em>) des Steuergeräts bzw. Fahrzeugs.</li>\n<li>Liefert den Zustand an den DoIP-Daemon zur Beantwortung von <em>Diagnostic Power Mode Information Requests</em> des externen DoIP-Testers.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell-Diagramm handelt, sind Laufzeitflüsse nicht direkt abgebildet. Das abgeleitete Zusammenspiel im System gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\">\n<li><strong>Aktivierung & Sockets (Activation Line):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein I/O-Treiber oder Hardware-Monitor detektiert Pegelwechsel an der physischen DoIP-Aktivierungsleitung.</li>\n<li>Benachrichtigung des Diagnostic Managers über einen Port mit <code>DiagnosticDoIPActivationLineInterface</code>.</li>\n<li>Der DoIP-Stack aktiviert seine IP-Sockets und startet die DoIP-Initialisierung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Vehicle Announcement:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Verbindungsaufbau (Link-Up/DHCP) oder getriggert via <code>DiagnosticDoIPTriggerVehicleAnnouncementInterface</code> sendet der DoIP-Stack bis zu 3x die Vehicle Announcement Message (VAM) an den Multicast-/Broadcast-Port 13400.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Statusabfragen (Power Mode & Group ID):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Geht ein DoIP-Request (z. B. <em>Power Mode Information Request</em>) vom Tester ein, ruft der Stack synchron/asynchron über das <code>DiagnosticDoIPPowerModeInterface</code> den Zustand beim Platform State Management ab und formuliert die DoIP-Response.</li>\n<li>Bei Gruppenzuordnung greift der Stack über das <code>DiagnosticDoIPGroupIdentificationInterface</code> auf hinterlegte Routing-Parameter zu.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Modellierung (ARXML):</strong></li>\n<li>Ports an <code>AdaptiveApplication</code>s oder Plattform-Daemons müssen explizit mit einer dieser Schnittstellen typisiert werden (<code>provided</code> oder <code>required PortPrototype</code>).</li>\n<li>Ein Service Instance Manifest mappt diese Port-Interfaces auf ara::com-Services oder plattforminterne direkte IPC-Bindings des Diagnostic Managers (DM).</li>\n<li><strong>API- & C++-Stack-Vertrag (<code>ara::diag</code>):</strong></li>\n<li>Implementierende Komponenten stellen Callback-Klassen bzw. Observer bereit, die den Schnittstellenfunktionalitäten entsprechen (z. B. Abfrage-Methoden für Power Mode oder Events für Statusänderungen der Activation Line).</li>\n<li>Fehlende oder inkorrekte Port-Definitionen im Execution Manifest verhindern das standardkonforme Starten des DoIP-Daemons bzw. führen zur Verweigerung von ISO 13400-Konformitätstests.</li>\n<li><strong>Systemintegration:</strong></li>\n<li>Entwickler von State Management und I/O-Basissoftware müssen zwingend das <code>DiagnosticDoIPActivationLineInterface</code> bedienen, um DoIP normgerecht (Batterieschutz bei ausgeschalteter Zündung) freizugeben oder schlafen zu legen.</li>\n</ul>"}, {"id": "FIG-f4a45266422dbccd", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt der AUTOSAR Adaptive Platform / <em>TPS Manifest Specification</em>).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation des Metamodells zur typisierten Anbindung von DoIP-spezifischen Steuerungs- und Signalisierungsfunktionen zwischen der AUTOSAR Adaptive Plattform (insbesondere dem Diagnostic Management / DoIP-Daemon) und Applikationen bzw. Basissoftware-Diensten. Es implementiert <code>RS_MANI_00061</code> (<em>Support the modeling of Diagnostic Port Interfaces</em>) und standardisiert portschnittstellenseitig die Interaktion für hardwarenahe und protokollspezifische DoIP-Funktionen (ISO 13400).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Basisklassen & Metamodell-Eigenschaften</p>\n<ul class=\"fig-list\">\n<li><strong><code>PortInterface</code>:</strong></li>\n<li>Abstrakte Basisklasse aller Port-Schnittstellen im AUTOSAR-Metamodell.</li>\n<li>Im Diagramm als übergeordnete Basisklasse im Header von <code>DiagnosticPortInterface</code> referenziert.</li>\n<li><strong><code>DiagnosticPortInterface</code>:</strong></li>\n<li>Abstrakte Spezialisierung von <code>PortInterface</code> (kursiv dargestellt).</li>\n<li>Dient als generische Basisklasse für sämtliche diagnostikspezifischen Port-Schnittstellen (Diagnostic Management) im AUTOSAR Adaptive Platform Modell.</li>\n</ul>\n<p class=\"fig-p\">#### DoIP-spezifische Spezialisierungen (<code>DiagnosticPortInterface</code>)</p>\n<p class=\"fig-p\">Alle fünf Subklassen erben transitiv die <code>PortInterface</code>-Eigenschaften und spezialisieren die Semantik für DoIP-Ereignisse und -Zustände gemäß ISO 13400:</p>\n<ol class=\"fig-list\">\n<li><strong><code>DiagnosticDoIPGroupIdentificationInterface</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Schnittstelle zur dynamischen Ermittlung oder Konfiguration der DoIP-Entity-/Gruppen-Identifikation (<em>Entity Group Identification</em> gemäß ISO 13400-2).</li>\n<li>Erlaubt dem DoIP-Stack, Gruppenidentifikationsdaten für Routing- und Adressierungszwecke abzufragen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>DiagnosticDoIPEntityIdentificationInterface</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Schnittstelle zur dynamischen Bereitstellung und Ermittlung von DoIP-Entitätsidentifikationsdaten (<em>Entity Identification</em>, EID / VIN).</li>\n<li>Erlaubt dem DoIP-Daemon die Abfrage von Identifikationsparametern zur Beantwortung von <em>DoIP Entity Identification Requests</em> bzw. zur Zusammensetzung von Identifikationsmeldungen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>DiagnosticDoIPTriggerVehicleAnnouncementInterface</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Triggerschnittstelle zur Initiierung von DoIP-<em>Vehicle Announcement Messages</em> (VAM).</li>\n<li>Ermöglicht externen oder internen Funktionen (z. B. Network Management, State Management), ein erneutes Versenden der Fahrzeugidentifikationsnachricht via UDP-Broadcast/Multicast anzustoßen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>DiagnosticDoIPActivationLineInterface</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signalisiert den logischen Zustand der hardwareseitigen DoIP-Aktivierungslinie (<em>DoIP Activation Line</em> gemäß ISO 13400-2).</li>\n<li>Steuert das Aktivieren/Deaktivieren der DoIP-Kommunikation und der TCP/UDP-Server-Sockets im Stack.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>DiagnosticDoIPPowerModeInterface</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Rückmeldeschnittstelle für den aktuellen Energiemodus (<em>Power Mode</em>) des Steuergeräts bzw. Fahrzeugs.</li>\n<li>Liefert den Zustand an den DoIP-Daemon zur Beantwortung von <em>Diagnostic Power Mode Information Requests</em> des externen DoIP-Testers.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell-Diagramm handelt, sind Laufzeitflüsse nicht direkt abgebildet. Das abgeleitete Zusammenspiel im System gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\">\n<li><strong>Aktivierung & Sockets (Activation Line):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein I/O-Treiber oder Hardware-Monitor detektiert Pegelwechsel an der physischen DoIP-Aktivierungsleitung.</li>\n<li>Benachrichtigung des Diagnostic Managers über einen Port mit <code>DiagnosticDoIPActivationLineInterface</code>.</li>\n<li>Der DoIP-Stack aktiviert seine IP-Sockets und startet die DoIP-Initialisierung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fahrzeugankündigung & Trigger (Vehicle Announcement):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Verbindungsaufbau oder getriggert über <code>DiagnosticDoIPTriggerVehicleAnnouncementInterface</code> versendet der DoIP-Daemon initiale <em>Vehicle Announcement Messages</em> via UDP-Broadcast/Multicast.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Entitäts- & Gruppenidentifikation (Entity & Group Identification):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei Eingang von <em>DoIP Entity Identification Requests</em> externer DoIP-Tester fragt der DoIP-Daemon dynamisch die Entitätsdaten (z. B. VIN, EID) über <code>DiagnosticDoIPEntityIdentificationInterface</code> ab.</li>\n<li>Die logische Zuordnung und Gruppenidentifikation wird parallel über <code>DiagnosticDoIPGroupIdentificationInterface</code> bezogen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Energiemodus-Status (Power Mode):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei Erhalt eines <em>Diagnostic Power Mode Information Request</em> fragt der DoIP-Daemon den aktuellen Energiemodus über <code>DiagnosticDoIPPowerModeInterface</code> ab und übermittelt diesen an den Tester.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Erweiterung:</strong> Mit der Einführung von <code>DiagnosticDoIPEntityIdentificationInterface</code> wird die Modellierung der DoIP-Identifikation vervollständigt. Neben der Gruppenidentifikation (GID) kann nun auch die spezifische Entitätsidentifikation (EID, VIN) über typisierte Port-Schnittstellen softwaregetrieben angebunden werden.</li>\n<li><strong>Entwickler-Hinweise:</strong> Entwickler können DoIP-Entitätsparameter flexibel gestalten; anstatt VIN und EID rein statisch im Diagnostic Manifest zu hinterlegen, ermöglicht das Interface eine dynamische Bereitstellung zur Laufzeit.</li>\n<li><strong>Port-Typisierung:</strong> Sämtliche Subklassen fungieren als Schnittstellentypen für <code>ProvidedPortPrototype</code> oder <code>RequiredPortPrototype</code> am Diagnostic Management bzw. den anbindenden Adaptive Applications.</li>\n</ul>"}, {"id": "FIG-8f9fc59e91e52ccb", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt der AUTOSAR Adaptive Platform / <em>TPS Manifest Specification</em>).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation des Metamodells zur typisierten Anbindung von DoIP-spezifischen Steuerungs- und Signalisierungsfunktionen zwischen der AUTOSAR Adaptive Plattform (insbesondere dem Diagnostic Management / DoIP-Daemon) und Applikationen bzw. Basissoftware-Diensten. Es implementiert <code>RS_MANI_00061</code> (<em>Support the modeling of Diagnostic Port Interfaces</em>) und standardisiert portschnittstellenseitig die Interaktion für hardwarenahe und protokollspezifische DoIP-Funktionen (ISO 13400).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Basisklassen & Metamodell-Eigenschaften</p>\n<ul class=\"fig-list\">\n<li><strong><code>PortInterface</code>:</strong></li>\n<li>Abstrakte Basisklasse aller Port-Schnittstellen im AUTOSAR-Metamodell.</li>\n<li>Im Diagramm als übergeordnete Basisklasse im Header von <code>DiagnosticPortInterface</code> referenziert.</li>\n<li><strong><code>DiagnosticPortInterface</code>:</strong></li>\n<li>Abstrakte Spezialisierung von <code>PortInterface</code> (kursiv dargestellt).</li>\n<li>Dient als generische Basisklasse für sämtliche diagnostikspezifischen Port-Schnittstellen (Diagnostic Management) im AUTOSAR Adaptive Platform Modell.</li>\n</ul>\n<p class=\"fig-p\">#### DoIP-spezifische Spezialisierungen (<code>DiagnosticPortInterface</code>)</p>\n<p class=\"fig-p\">Alle fünf Subklassen erben transitiv die <code>PortInterface</code>-Eigenschaften und spezialisieren die Semantik für DoIP-Ereignisse und -Zustände gemäß ISO 13400:</p>\n<ol class=\"fig-list\">\n<li><strong><code>DiagnosticDoIPGroupIdentificationInterface</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Schnittstelle zur dynamischen Ermittlung oder Konfiguration der DoIP-Entity-/Gruppen-Identifikation (<em>Entity Group Identification</em> gemäß ISO 13400-2).</li>\n<li>Erlaubt dem DoIP-Stack, Gruppenidentifikationsdaten für Routing- und Adressierungszwecke abzufragen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>DiagnosticDoIPEntityIdentificationInterface</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Schnittstelle zur dynamischen Bereitstellung und Ermittlung von DoIP-Entitätsidentifikationsdaten (<em>Entity Identification</em>, EID / VIN).</li>\n<li>Erlaubt dem DoIP-Daemon die Abfrage von Identifikationsparametern zur Beantwortung von <em>DoIP Entity Identification Requests</em> bzw. zur Zusammensetzung von Identifikationsmeldungen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>DiagnosticDoIPTriggerVehicleAnnouncementInterface</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Triggerschnittstelle zur Initiierung von DoIP-<em>Vehicle Announcement Messages</em> (VAM).</li>\n<li>Ermöglicht externen oder internen Funktionen (z. B. Network Management, State Management), ein erneutes Versenden der Fahrzeugidentifikationsnachricht via UDP-Broadcast/Multicast anzustoßen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>DiagnosticDoIPActivationLineInterface</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signalisiert den logischen Zustand der hardwareseitigen DoIP-Aktivierungslinie (<em>DoIP Activation Line</em> gemäß ISO 13400-2).</li>\n<li>Steuert das Aktivieren/Deaktivieren der DoIP-Kommunikation und der TCP/UDP-Server-Sockets im Stack.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>DiagnosticDoIPPowerModeInterface</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Rückmeldeschnittstelle für den aktuellen Energiemodus (<em>Power Mode</em>) des Steuergeräts bzw. Fahrzeugs.</li>\n<li>Liefert den Zustand an den DoIP-Daemon zur Beantwortung von <em>Diagnostic Power Mode Information Requests</em> des externen DoIP-Testers.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell-Diagramm handelt, sind Laufzeitflüsse nicht direkt abgebildet. Das abgeleitete Zusammenspiel im System gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\">\n<li><strong>Aktivierung & Sockets (Activation Line):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein I/O-Treiber oder Hardware-Monitor detektiert Pegelwechsel an der physischen DoIP-Aktivierungsleitung.</li>\n<li>Benachrichtigung des Diagnostic Managers über einen Port mit <code>DiagnosticDoIPActivationLineInterface</code>.</li>\n<li>Der DoIP-Stack aktiviert seine IP-Sockets und startet die DoIP-Initialisierung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fahrzeugankündigung & Trigger (Vehicle Announcement):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Verbindungsaufbau oder getriggert über <code>DiagnosticDoIPTriggerVehicleAnnouncementInterface</code> versendet der DoIP-Daemon initiale <em>Vehicle Announcement Messages</em> via UDP-Broadcast/Multicast.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Entitäts- & Gruppenidentifikation (Entity & Group Identification):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei Eingang von <em>DoIP Entity Identification Requests</em> externer DoIP-Tester fragt der DoIP-Daemon dynamisch die Entitätsdaten (z. B. VIN, EID) über <code>DiagnosticDoIPEntityIdentificationInterface</code> ab.</li>\n<li>Die logische Zuordnung und Gruppenidentifikation wird parallel über <code>DiagnosticDoIPGroupIdentificationInterface</code> bezogen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Energiemodus-Status (Power Mode):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei Erhalt eines <em>Diagnostic Power Mode Information Request</em> fragt der DoIP-Daemon den aktuellen Energiemodus über <code>DiagnosticDoIPPowerModeInterface</code> ab und übermittelt diesen an den Tester.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Erweiterung:</strong> Mit der Einführung von <code>DiagnosticDoIPEntityIdentificationInterface</code> wird die Modellierung der DoIP-Identifikation vervollständigt. Neben der Gruppenidentifikation (GID) kann nun auch die spezifische Entitätsidentifikation (EID, VIN) über typisierte Port-Schnittstellen softwaregetrieben angebunden werden.</li>\n<li><strong>Entwickler-Hinweise:</strong> Entwickler können DoIP-Entitätsparameter flexibel gestalten; anstatt VIN und EID rein statisch im Diagnostic Manifest zu hinterlegen, ermöglicht das Interface eine dynamische Bereitstellung zur Laufzeit.</li>\n<li><strong>Port-Typisierung:</strong> Sämtliche Subklassen fungieren als Schnittstellentypen für <code>ProvidedPortPrototype</code> oder <code>RequiredPortPrototype</code> am Diagnostic Management bzw. den anbindenden Adaptive Applications.</li>\n</ul>"}, {"id": "FIG-ff99f5293c2da583", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt der AUTOSAR Adaptive Platform / <em>TPS Manifest Specification</em>).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation des Metamodells zur typisierten Anbindung von DoIP-spezifischen Steuerungs- und Signalisierungsfunktionen zwischen der AUTOSAR Adaptive Plattform (insbesondere dem Diagnostic Management / DoIP-Daemon) und Applikationen bzw. Basissoftware-Diensten. Es implementiert <code>RS_MANI_00061</code> (<em>Support the modeling of Diagnostic Port Interfaces</em>) und standardisiert portschnittstellenseitig die Interaktion für hardwarenahe und protokollspezifische DoIP-Funktionen (ISO 13400).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Basisklassen & Metamodell-Eigenschaften</p>\n<ul class=\"fig-list\">\n<li><strong><code>PortInterface</code>:</strong></li>\n<li>Abstrakte Basisklasse aller Port-Schnittstellen im AUTOSAR-Metamodell.</li>\n<li>Im Diagramm als übergeordnete Basisklasse im Header von <code>DiagnosticPortInterface</code> referenziert.</li>\n<li><strong><code>DiagnosticPortInterface</code>:</strong></li>\n<li>Abstrakte Spezialisierung von <code>PortInterface</code> (kursiv dargestellt).</li>\n<li>Dient als generische Basisklasse für sämtliche diagnostikspezifischen Port-Schnittstellen (Diagnostic Management) im AUTOSAR Adaptive Platform Modell.</li>\n</ul>\n<p class=\"fig-p\">#### DoIP-spezifische Spezialisierungen (<code>DiagnosticPortInterface</code>)</p>\n<p class=\"fig-p\">Alle fünf Subklassen erben transitiv die <code>PortInterface</code>-Eigenschaften und spezialisieren die Semantik für DoIP-Ereignisse und -Zustände gemäß ISO 13400:</p>\n<ol class=\"fig-list\">\n<li><strong><code>DiagnosticDoIPGroupIdentificationInterface</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Schnittstelle zur dynamischen Ermittlung oder Konfiguration der DoIP-Entity-/Gruppen-Identifikation (<em>Entity Group Identification</em> gemäß ISO 13400-2).</li>\n<li>Erlaubt dem DoIP-Stack, Gruppenidentifikationsdaten für Routing- und Adressierungszwecke abzufragen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>DiagnosticDoIPEntityIdentificationInterface</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Schnittstelle zur dynamischen Bereitstellung und Ermittlung von DoIP-Entitätsidentifikationsdaten (<em>Entity Identification</em>, EID / VIN).</li>\n<li>Erlaubt dem DoIP-Daemon die Abfrage von Identifikationsparametern zur Beantwortung von <em>DoIP Entity Identification Requests</em> bzw. zur Zusammensetzung von Identifikationsmeldungen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>DiagnosticDoIPTriggerVehicleAnnouncementInterface</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Triggerschnittstelle zur Initiierung von DoIP-<em>Vehicle Announcement Messages</em> (VAM).</li>\n<li>Ermöglicht externen oder internen Funktionen (z. B. Network Management, State Management), ein erneutes Versenden der Fahrzeugidentifikationsnachricht via UDP-Broadcast/Multicast anzustoßen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>DiagnosticDoIPActivationLineInterface</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signalisiert den logischen Zustand der hardwareseitigen DoIP-Aktivierungslinie (<em>DoIP Activation Line</em> gemäß ISO 13400-2).</li>\n<li>Steuert das Aktivieren/Deaktivieren der DoIP-Kommunikation und der TCP/UDP-Server-Sockets im Stack.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>DiagnosticDoIPPowerModeInterface</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Rückmeldeschnittstelle für den aktuellen Energiemodus (<em>Power Mode</em>) des Steuergeräts bzw. Fahrzeugs.</li>\n<li>Liefert den Zustand an den DoIP-Daemon zur Beantwortung von <em>Diagnostic Power Mode Information Requests</em> des externen DoIP-Testers.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell-Diagramm handelt, sind Laufzeitflüsse nicht direkt abgebildet. Das abgeleitete Zusammenspiel im System gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\">\n<li><strong>Aktivierung & Sockets (Activation Line):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein I/O-Treiber oder Hardware-Monitor detektiert Pegelwechsel an der physischen DoIP-Aktivierungsleitung.</li>\n<li>Benachrichtigung des Diagnostic Managers über einen Port mit <code>DiagnosticDoIPActivationLineInterface</code>.</li>\n<li>Der DoIP-Stack aktiviert seine IP-Sockets und startet die DoIP-Initialisierung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fahrzeugankündigung & Trigger (Vehicle Announcement):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Verbindungsaufbau oder getriggert über <code>DiagnosticDoIPTriggerVehicleAnnouncementInterface</code> versendet der DoIP-Daemon initiale <em>Vehicle Announcement Messages</em> via UDP-Broadcast/Multicast.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Entitäts- & Gruppenidentifikation (Entity & Group Identification):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei Eingang von <em>DoIP Entity Identification Requests</em> externer DoIP-Tester fragt der DoIP-Daemon dynamisch die Entitätsdaten (z. B. VIN, EID) über <code>DiagnosticDoIPEntityIdentificationInterface</code> ab.</li>\n<li>Die logische Zuordnung und Gruppenidentifikation wird parallel über <code>DiagnosticDoIPGroupIdentificationInterface</code> bezogen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Energiemodus-Status (Power Mode):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei Erhalt eines <em>Diagnostic Power Mode Information Request</em> fragt der DoIP-Daemon den aktuellen Energiemodus über <code>DiagnosticDoIPPowerModeInterface</code> ab und übermittelt diesen an den Tester.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Erweiterung:</strong> Mit der Einführung von <code>DiagnosticDoIPEntityIdentificationInterface</code> wird die Modellierung der DoIP-Identifikation vervollständigt. Neben der Gruppenidentifikation (GID) kann nun auch die spezifische Entitätsidentifikation (EID, VIN) über typisierte Port-Schnittstellen softwaregetrieben angebunden werden.</li>\n<li><strong>Entwickler-Hinweise:</strong> Entwickler können DoIP-Entitätsparameter flexibel gestalten; anstatt VIN und EID rein statisch im Diagnostic Manifest zu hinterlegen, ermöglicht das Interface eine dynamische Bereitstellung zur Laufzeit.</li>\n<li><strong>Port-Typisierung:</strong> Sämtliche Subklassen fungieren als Schnittstellentypen für <code>ProvidedPortPrototype</code> oder <code>RequiredPortPrototype</code> am Diagnostic Management bzw. den anbindenden Adaptive Applications.</li>\n</ul>"}], "trans": [{"from": "FIG-b8cc5c2834dd3832", "to": "FIG-35b7b7ef71de12fe", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-35b7b7ef71de12fe", "to": "FIG-230ed2690c04d519", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>PortInterface</code>: Die eigenständige Klassendarstellung mit den Stereotypen <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AtpType</code> sowie die Vererbungskante wurden entfernt; <code>PortInterface</code> wird stattdessen als Superklasse in der oberen rechten Ecke von <code>DiagnosticPortInterface</code> referenziert.</li>\n</ul>"}, {"from": "FIG-230ed2690c04d519", "to": "FIG-f4a45266422dbccd", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>DiagnosticDoIPEntityIdentificationInterface</code>: Neue Schnittstellenklasse als Spezialisierung von <code>DiagnosticPortInterface</code> hinzugefügt.</li>\n</ul>"}, {"from": "FIG-f4a45266422dbccd", "to": "FIG-8f9fc59e91e52ccb", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8f9fc59e91e52ccb", "to": "FIG-ff99f5293c2da583", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
